// Do not edit: change the source test and regenerate.
//! The default build is the mainnet build. It must answer exactly the thirteen V1
//! instructions and treat everything else, including the rating, attestation
//! and PER instructions kept behind the `extended` feature, as unknown.
//!
//! This is checked against the built program, not the source: each call is sent
//! with no accounts, so a known instruction fails on its missing accounts while
//! an unknown one fails with Anchor's "fallback not found" error.
#![cfg(not(feature = "extended"))]

use anchor_lang::solana_program::instruction::Instruction;
use litesvm::LiteSVM;
use sha2::{Digest, Sha256};
use solana_keypair::Keypair;
use solana_message::{Message, VersionedMessage};
use solana_signer::Signer;
use solana_transaction::versioned::VersionedTransaction;

const V1_INSTRUCTIONS: [&str; 13] = [
    "lock_escrow",
    "lock_metered_escrow",
    "release_escrow",
    "settle_escrow",
    "cancel_escrow",
    "lock_token_escrow",
    "lock_metered_token_escrow",
    "release_token_escrow",
    "settle_token_escrow",
    "cancel_token_escrow",
    "register_agent",
    "update_agent",
    "deregister_agent",
];

const EXTENDED_INSTRUCTIONS: [&str; 8] = [
    "commit_rating",
    "reveal_rating",
    "expire_rating",
    "delegate_escrow",
    "release_escrow_per",
    "attest_quality",
    "confirm_attestation",
    "dispute_attestation",
];

/// Anchor's InstructionFallbackNotFound.
const UNKNOWN_INSTRUCTION: &str = "Custom(101)";

fn call(name: &str) -> String {
    let mut svm = LiteSVM::new();
    svm.add_program(
        escrow::id(),
        include_bytes!("../../target/deploy/pinocchio_escrow.so"),
    )
    .unwrap();
    let payer = Keypair::new();
    svm.airdrop(&payer.pubkey(), 1_000_000_000).unwrap();
    let digest = Sha256::digest(format!("global:{name}").as_bytes());
    let ix = Instruction::new_with_bytes(escrow::id(), &digest[..8], vec![]);
    let msg = Message::new_with_blockhash(&[ix], Some(&payer.pubkey()), &svm.latest_blockhash());
    let tx = VersionedTransaction::try_new(VersionedMessage::Legacy(msg), &[&payer]).unwrap();
    format!(
        "{:?}",
        svm.send_transaction(tx)
            .expect_err("a call with no accounts can never succeed")
            .err
    )
}

#[test]
fn default_build_answers_the_thirteen_v1_instructions() {
    for name in V1_INSTRUCTIONS {
        let err = call(name);
        assert!(
            !err.contains(UNKNOWN_INSTRUCTION),
            "{name} must be part of the default build, got: {err}"
        );
    }
}

#[test]
fn default_build_does_not_answer_extended_instructions() {
    for name in EXTENDED_INSTRUCTIONS {
        let err = call(name);
        assert!(
            err.contains(UNKNOWN_INSTRUCTION),
            "{name} must not be part of the default build, got: {err}"
        );
    }
}

#[test]
fn an_arbitrary_instruction_is_unknown() {
    assert!(call("withdraw_everything").contains(UNKNOWN_INSTRUCTION));
}
